# -*- coding: utf-8 -*-
import os, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')
ROOT = r'D:\repository'
SKIP = {'node_modules','.git','dist','.cache','coverage','vendor','temp','__pycache__'}
def scan(repo, pathsub, token, include_hidden=False):
    base=os.path.join(ROOT,repo); out=[]
    for dp,dns,fns in os.walk(base) if os.path.isdir(base) else []:
        dns[:]=[d for d in dns if d not in SKIP and (include_hidden or not d.startswith('.'))]
        for fn in fns:
            p=os.path.join(dp,fn); pl=p.replace('/','\\').lower()
            if pathsub.lower().replace('/','\\') in pl:
                if token:
                    try: t=open(p,encoding='utf-8',errors='ignore').read().lower()
                    except: continue
                    if token.lower() in t: out.append(p)
                else: out.append(p)
    return out
